// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/proposals/catalog", wrapper.ListCatalog)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/proposals/catalog", wrapper.CreateCatalogItem)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/proposals/catalog/{id}", wrapper.UpdateCatalogItem)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/proposals/text-templates", wrapper.ListTextTemplates)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/proposals/text-templates", wrapper.CreateTextTemplate)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/proposals/text-templates/{kind}/{id}", wrapper.UpdateTextTemplate)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/proposals/templates", wrapper.ListTemplates)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/proposals/templates", wrapper.CreateTemplate)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/proposals/templates/{id}", wrapper.UpdateTemplate)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/proposals/proposals", wrapper.ListProposals)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/proposals/proposals", wrapper.CreateProposal)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/proposals/proposals/{id}", wrapper.DeleteProposal)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/proposals/proposals/{id}", wrapper.GetProposal)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/proposals/proposals/{id}/activity", wrapper.GetProposalActivity)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/proposals/proposals/{id}/versions", wrapper.CreateVersion)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/proposals/proposals/{id}/versions/{version}", wrapper.GetVersion)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/proposals/proposals/{id}/versions/{version}", wrapper.EditVersion)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/proposals/proposals/{id}/versions/{version}/calculate", wrapper.CalculateVersion)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/proposals/proposals/{id}/versions/{version}/ai-draft", wrapper.AiDraft)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/proposals/proposals/{id}/versions/{version}/submit", wrapper.SubmitVersion)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/proposals/proposals/{id}/versions/{version}/approve", wrapper.ApproveVersion)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/proposals/proposals/{id}/versions/{version}/reject", wrapper.RejectVersion)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/proposals/proposals/{id}/versions/{version}/issue", wrapper.IssueVersion)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/proposals/proposals/{id}/versions/{version}/signature-requests", wrapper.RequestSignature)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/proposals/share-links/{id}/revoke", wrapper.RevokeShareLink)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/public/proposals/{token}", wrapper.ViewPublicProposal)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/public/proposals/{token}/pdf", wrapper.DownloadPublicProposal)
	})

	return r
}

